//Get the vector distance between crate's origin point and vendor that's being interacted with
const Distance = GetDistanceBetween(GetSourceNode(), GetTargetNode());
// Minimum movement speed on Caravans
const CaravanMovespeed = 2.0;
//Multipler for PvP Event
const PvPMult = 1;
//Copper earned per minute at level 10
const CopperPerMinute = 44.80716915;
//Minium amount of copper expected to earn per crate per trip
const MinAmountCopperEarned = 805.1997224;
//Distance Multiplier calculation
const DistanceMult = (Distance / 100 / CaravanMoveSpeed / 60) * CopperPerMinute / MinAmountCopperEarned;
//Getting the origin node and destination node by checking the crate's origin and player's location to get the economic region multiplier
const EconomicRegionMult = GetEconomicRegionMultiplierFromNodeToNode(GetSourceNode(),GetTargetNode());
//Getting the turn in multiplier from a curve that checks how many turn in has happened at destination node
const TurnInMult = EvalCurve($#10516612381411114:6064634053976784898$, Float(GetTurnInOverPreviousDays()));
//The final multiplier that gets multiplied to 
var FinalMult = 1.0;

//Set the final mult to be 0.1 when it's from the same node
if((ItemTypeTagsContains("Item.Crate.Commodity.Market") || 
ItemTypeTagsContains("Item.Crate.Commodity.Node") || 
ItemTypeTagsContains("Item.Crate.Commodity.Citizen") || 
ItemTypeTagsContains("Item.Crate.Commodity.Construction") || 
ItemTypeTagsContains("Item.Crate.Commodity.Guild") || 
ItemTypeTagsContains("Item.Crate.Commodity.Harbor")) == true){
    if(GetSourceNode() == GetTargetNode()){
        if(GetBaseItemValue()<10.0){
            set FinalMult = 1.0;
        }else{
            set FinalMult = 0.1;
        }
    }else{
        set FinalMult = DistanceMult * EconomicRegionMult * TurnInMult;
    }
}

